import { IVersion } from '../types';

function toNumber(value: string = '0'): number {
    let numberValue = parseInt(value, 10);

    if (isNaN(numberValue)) {
        numberValue = 0;
    }

    return numberValue;
}

export enum VersionComparison {
    EQUAL_TO = 0,
    GREATER_THAN = 1,
    LESS_THAN = 2
}

export class Version implements IVersion {
    public major: number;

    public minor: number;

    public patch: number;

    public build: number;

    private version: string;

    constructor(version: string = '0.0.0+0') {
        const parsed = String(version).toLowerCase().replace(/_/g, '.').replace(/-{2,}/g, '-').replace(/-/g, '.');
        const parts = parsed.split('.');

        this.version = version;
        this.major = toNumber(parts.shift());
        this.minor = toNumber(parts.shift());
        this.patch = toNumber(parts.shift());
        this.build = 0;

        const buildStartIndex = parsed.search(/([^\d.])/);

        if (buildStartIndex !== -1) {
            this.build = toNumber(this.version.substr(buildStartIndex + 1, version.length) || '');
        }
    }

    public isGreaterThan(target: string | Version, equals: boolean = false): boolean {
        return equals ?
            (this.compare(target) >= VersionComparison.EQUAL_TO) :
            (this.compare(target) === VersionComparison.GREATER_THAN);
    }

    public isLessThan(target: string | Version, equals: boolean = false): boolean {
        return equals ?
            (this.compare(target) <= VersionComparison.EQUAL_TO) :
            (this.compare(target) === VersionComparison.LESS_THAN);
    }

    public toArray(): number[] {
        return [this.major, this.minor, this.patch, this.build];
    }

    public toString(): string {
        return this.version;
    }

    private compare(target: string | Version): number {
        let currentValue: number;
        let targetValue: number;

        const currentArray = this.toArray();
        const targetArray = (target instanceof Version) ? target.toArray() : new Version(target).toArray();
        const length = Math.max(currentArray.length, targetArray.length);

        for (let index = 0; index < length; index++) {
            currentValue = currentArray[index];
            targetValue = targetArray[index];

            if (currentValue < targetValue) {
                return VersionComparison.LESS_THAN;
            } else {
                if (currentValue > targetValue) {
                    return VersionComparison.GREATER_THAN;
                }
            }
        }

        return VersionComparison.EQUAL_TO;
    }
}
